for m in ['meaning', 'hybrid']:
    tests[m] = [rank_of(m, q, g) for q, g in zip(tests.question, tests.gold_doc_id)]

def recall_at(col, k):
    r = tests[col]
    return ((r > 0) & (r <= k)).mean()

def mrr_of(col):
    r = tests[col]
    return (1 / r.where(r > 0)).fillna(0).mean()

scores = pd.DataFrame({m: {'recall@3': recall_at(m, 3), 'recall@5': recall_at(m, 5), 'MRR': mrr_of(m)} for m in ['bm25', 'meaning', 'hybrid']}).round(3)
print(scores)
